package store

import "time"

// ExportPlan preserves fixed membership and, in v2, references to committed
// generation pages, never generated bytes or ledger truth. It has no query
// cursor lifetime. Only active fenced running jobs may retain one; progress
// and transition to a sealed checkpoint use the same control CAS.
// No payload, ciphertext, raw filter/search digest or lease owner is copied.
type ExportPlan struct {
	Version       int                `json:"version"`
	FormatVersion int                `json:"format_version"`
	JobID         string             `json:"job_id"`
	TenantID      string             `json:"tenant_id"`
	Binding       string             `json:"binding"`
	CreatedAt     time.Time          `json:"created_at"`
	Members       []ExportPlanMember `json:"members"`
	Chunks        []ExportPlanChunk  `json:"chunks,omitempty"`
	Signature     string             `json:"signature"`
}

type ExportPlanMember struct {
	EventReference
	SchemaID      string `json:"schema_id"`
	SchemaVersion int    `json:"schema_version"`
	SchemaDigest  string `json:"schema_digest"`
}

// ExportPlanChunk references one authenticated JSONL page in immutable storage.
// First/Count form a contiguous prefix of Members, not a live query cursor.
// The page's AEAD binds the immutable plan, ordinal, range and object identity.
type ExportPlanChunk struct {
	SealVersion  int       `json:"seal_version"`
	First        int       `json:"first"`
	Count        int       `json:"count"`
	ObjectPath   string    `json:"object_path"`
	SealedDigest string    `json:"sealed_digest"`
	Digest       string    `json:"digest"`
	CreatedAt    time.Time `json:"created_at"`
}

// V2 plans generate fixed pages. Single-page exports and retained v1 plans keep
// the compatible whole-object path. This is not a byte/streaming capacity SLA.
const ExportGenerationPageEvents = 100

// Reuse the established identity/byte budgets, not the short query TTL or its
// per-tenant active-query allowance. Plans occupy the existing running slots.
const MaxExportPlanEvents = MaxQuerySnapshotEvents
const MaxExportPlanBytes = MaxQuerySnapshotBytes
